import AxolotyWire
import Foundation
import Testing

/// Golden corpus verification for the `coaty/3` JSON and `axoloty/1` CBOR wire
/// profiles (epic #977).
///
/// The frozen corpus under `WireCompatibility/Golden` is generated by
/// `Tests/Support/WireCompatibility/tool` (`npm run golden:generate`). Every
/// case carries a compact JSON golden and a deterministic CBOR golden for the
/// same typed payload.
///
/// This suite proves two things without touching the network:
///
/// 1. `coaty/3` JSON goldens decode and re-encode byte-identically, so the
///    shared codec seam did not change field presence or JSON bytes.
/// 2. `axoloty/1` CBOR goldens decode and re-encode byte-identically, so the
///    deterministic CBOR writer and the raw-payload splice stay stable.
///
/// Independent, non-Axoloty decoding of every CBOR golden is a separate check
/// in the wire tool (`npm run verify:golden`, tier node
/// `wire-golden-independent`).
@Suite("Golden wire corpus")
struct WireGoldenCorpusTests {
    /// A decoded corpus manifest.
    struct Manifest: Decodable {
        struct Case: Decodable {
            let id: String
            let family: String
            let variant: String
            let json: String
            let cbor: String
            let uuidPointers: [String]
            /// True when the JSON golden is a documented surrogate for a
            /// CBOR-only value, such as the hex string that stands in for a
            /// byte string.
            let jsonSurrogate: Bool
        }

        let schemaVersion: Int
        let description: String
        let cases: [Case]
    }

    /// A corpus load failure.
    enum CorpusError: Error, LocalizedError {
        case resource(String)
        case unknownFamily(String)

        var errorDescription: String? {
            switch self {
            case .resource(let name):
                return "golden corpus resource not found: \(name)"
            case .unknownFamily(let family):
                return "golden corpus case has unknown family: \(family)"
            }
        }
    }

    private static let expectedFamilies: Set<String> = [
        "advertise", "deadvertise", "channel", "associate", "ioValue", "discover",
        "resolve", "query", "retrieve", "update", "complete", "call", "return", "ioState"
    ]

    // MARK: - Loading

    /// Finds the checked-in corpus directory in the test resource bundle, then
    /// in the source checkout.
    private func corpusDirectory() throws -> URL {
        if let flat = Bundle.module.url(forResource: "manifest", withExtension: "json") {
            return flat.deletingLastPathComponent()
        }
        let relativePaths = [
            "Golden/manifest.json",
            "WireCompatibility/Golden/manifest.json",
            "Fixtures/Golden/manifest.json"
        ]
        let resourceURL = relativePaths.lazy
            .map { Bundle.module.resourceURL?.appendingPathComponent($0) }
            .compactMap { $0 }
            .first { FileManager.default.fileExists(atPath: $0.path) }
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Golden/manifest.json")
        let manifestURL = resourceURL ?? (FileManager.default.fileExists(atPath: sourceURL.path) ? sourceURL : nil)
        guard let manifestURL else {
            throw CorpusError.resource("Golden/manifest.json")
        }
        return manifestURL.deletingLastPathComponent()
    }

    private func manifest() throws -> Manifest {
        let directory = try corpusDirectory()
        let data = try Data(contentsOf: directory.appendingPathComponent("manifest.json"))
        return try JSONDecoder().decode(Manifest.self, from: data)
    }

    private func bytes(_ case: Manifest.Case, _ directory: URL, _ name: String) throws -> [UInt8] {
        let data = try Data(contentsOf: directory.appendingPathComponent(name))
        return [UInt8](data)
    }

    // MARK: - Codec helpers

    /// Decodes one DTO from a byte array that stays alive for the caller's
    /// scope, because the returned DTO borrows the array's storage.
    private func decode<T: WireDecodable>(
        _ profile: WireProfile, _ bytes: [UInt8], as _: T.Type = T.self
    ) throws -> T {
        try bytes.withUnsafeBufferPointer { buffer in
            let reader = WireCodec(profile: profile).reader(
                bytes: buffer.baseAddress!,
                length: buffer.count
            )
            return try T(from: reader)
        }
    }

    private func encode<T: WireEncodable>(_ profile: WireProfile, _ value: T) throws -> [UInt8] {
        var output = [UInt8](repeating: 0, count: WireBufferConfig.maxPayloadSize)
        let count = try output.withUnsafeMutableBufferPointer { buffer -> Int in
            var writer = WireCodec(profile: profile).writer(
                buffer: buffer.baseAddress!,
                capacity: buffer.count
            )
            try value.encode(to: &writer)
            return writer.position
        }
        return Array(output[0..<count])
    }

    /// Decodes and re-encodes one golden through the DTO selected by `family`.
    private func reencode(
        family: String, profile: WireProfile, bytes: [UInt8]
    ) throws -> [UInt8] {
        switch family {
        case "advertise": return try reencode(profile, bytes, as: AdvertiseWireData.self)
        case "deadvertise": return try reencode(profile, bytes, as: DeadvertiseWireData.self)
        case "channel": return try reencode(profile, bytes, as: ChannelWireData.self)
        case "associate": return try reencode(profile, bytes, as: AssociateWireData.self)
        case "ioValue": return try reencode(profile, bytes, as: IoValueWireData.self)
        case "discover": return try reencode(profile, bytes, as: DiscoverWireData.self)
        case "resolve": return try reencode(profile, bytes, as: ResolveWireData.self)
        case "query": return try reencode(profile, bytes, as: QueryWireData.self)
        case "retrieve": return try reencode(profile, bytes, as: RetrieveWireData.self)
        case "update": return try reencode(profile, bytes, as: UpdateWireData.self)
        case "complete": return try reencode(profile, bytes, as: CompleteWireData.self)
        case "call": return try reencode(profile, bytes, as: CallWireData.self)
        case "return": return try reencode(profile, bytes, as: ReturnWireData.self)
        case "ioState": return try reencode(profile, bytes, as: IoStateWireData.self)
        default: throw CorpusError.unknownFamily(family)
        }
    }

    private func reencode<T: WireDecodable & WireEncodable>(
        _ profile: WireProfile, _ bytes: [UInt8], as _: T.Type
    ) throws -> [UInt8] {
        let value = try decode(profile, bytes, as: T.self)
        return try encode(profile, value)
    }

    // MARK: - Tests

    @Test("every event family and field-presence variant is present")
    func coverage() throws {
        let manifest = try manifest()
        #expect(manifest.schemaVersion == 1)
        let families = Set(manifest.cases.map(\.family))
        #expect(families == Self.expectedFamilies)
        for family in ["channel", "discover", "query", "complete", "call", "return"] {
            let variants = manifest.cases.filter { $0.family == family }.map(\.variant)
            #expect(variants.contains("empty"), "\(family) must include an all-optional-absent case")
        }
        #expect(manifest.cases.count >= 28)
        let bytes = manifest.cases.first { $0.id == "iovalue-bytes" }
        #expect(bytes?.jsonSurrogate == true, "the byte-string golden must declare its JSON surrogate")
    }

    @Test("coaty/3 JSON goldens re-encode byte-identically")
    func jsonByteIdentity() throws {
        let directory = try corpusDirectory()
        let manifest = try manifest()
        for `case` in manifest.cases {
            let golden = try bytes(`case`, directory, `case`.json)
            let roundTripped = try reencode(family: `case`.family, profile: .coaty3JSON, bytes: golden)
            #expect(roundTripped == golden, "\(`case`.id): coaty/3 JSON bytes changed")
        }
    }

    @Test("axoloty/1 CBOR goldens re-encode byte-identically")
    func cborByteIdentity() throws {
        let directory = try corpusDirectory()
        let manifest = try manifest()
        for `case` in manifest.cases {
            let golden = try bytes(`case`, directory, `case`.cbor)
            let roundTripped = try reencode(family: `case`.family, profile: .axoloty1CBOR, bytes: golden)
            #expect(roundTripped == golden, "\(`case`.id): axoloty/1 CBOR bytes changed")
        }
    }
}
